console.log('rt_variants for PROD-FA0948:', variants.length, variants);

// Also check the compatible products
const compat = db.prepare(\"SELECT product_id, name, category FROM products WHERE product_id IN ('PROD-B98D14','PROD-73FAB4')\").all();
